<template><article v-if="post" class="article-page" dir="rtl"><div class="article-hero"><a href="/blog" class="back"><ArrowRight :size="16"/> بازگشت به مجله</a><div class="article-meta"><span>{{ post.category || 'مجله' }}</span><i>·</i>{{ post.read_time }} دقیقه مطالعه</div><h1>{{ post.title }}</h1><p>{{ post.excerpt }}</p><img v-if="post.cover_image" class="article-cover" :src="post.cover_image" :alt="post.title"></div><div class="article-layout"><div class="article-body" v-html="post.body_html"></div><aside v-if="post.related_products?.length" class="article-products"><h2>محصولات این مقاله</h2><a v-for="item in post.related_products" :key="item.item_code" :href="item.url" class="article-product"><img v-if="item.image" :src="item.image" :alt="item.title"><span v-else class="product-placeholder"><ShoppingBag :size="22"/></span><span><b>{{ item.title }}</b><small>{{ item.note || 'دیدن جزئیات محصول' }}</small></span><ArrowLeft :size="17"/></a></aside></div></article><div v-else class="article-state" dir="rtl">{{ loading?'در حال دریافت مقاله...':'این مقاله پیدا نشد.' }} <a href="/blog">بازگشت به مجله</a></div></template>
<script setup>
import { onMounted,ref } from 'vue'
import { ArrowLeft,ArrowRight,ShoppingBag } from 'lucide-vue-next'
import { getPublicBlogPost } from '@/utils/api'
const post=ref(null),loading=ref(true)
onMounted(async()=>{const route=decodeURIComponent(location.pathname.replace(/^\/blog\/?/,''));try{post.value=(await getPublicBlogPost({route}))?.post||null}catch{post.value=null}finally{loading.value=false}})
</script>
