ild(2){display:grid;gap:.2rem;flex:1}.article-product b{font-size:.85rem}.article-product small{font-size:.73rem;color:var(--ds-color-text-secondary)}.article-product>svg{color:var(--ds-color-action-primary)}.article-state{text-align:center;padding:6rem 1rem;color:var(--ds-color-text-secondary)}.article-state a{display:block;margin-top:1rem;color:var(--ds-color-action-primary)}@media(max-width:760px){.article-layout{grid-template-columns:1fr}.article-products{position:static}.article-body{font-size:.96rem}}
